 const match = router([...itemRoutes, ...batchRoutes, ...orderRoutes, ...kitchenRoutes, ...planningRoutes, ...safetyRoutes]);

+function requestLanguage(headers) {
+  const header = Object.entries(headers).find(([name]) => name.toLowerCase() === "accept-language")?.[1];
+  let best = config.defaultLanguage;
+  let bestQuality = 0;
+  for (const entry of String(header ?? "").split(",")) {
+    const [range, weight] = entry.trim().toLowerCase().split(/\s*;\s*/);
+    if (!/^[a-z]{2}(?:-[a-z0-9]{1,8})*$/.test(range)) continue;
+    const [language] = range.split("-");
+    if (!LANGUAGES.includes(language)) continue;
+    const quality = weight === undefined
+      ? 1
+      : Number(/^q\s*=\s*(0(?:\.\d{0,3})?|1(?:\.0{0,3})?|\.\d{1,3})$/.exec(weight)?.[1]);
+    if (quality > bestQuality) {
+      best = language;
+      bestQuality = quality;
+    }
+  }
+  return best;
+}
